using System.Text.Json;
using LiveAdDesk;
namespace LiveAdStudio;
static class UpgradeChecks
{
    public static void Run(string output)
    {
        var results=new List<string>();
        void Check(string name,Func<bool> test){try{results.Add((test()?"PASS ":"FAIL ")+name);}catch(Exception e){results.Add("FAIL "+name+": "+e.GetType().Name+" "+e.Message);}}
        Check("OCR scales ten-thousand and hundred-million units",()=>{var x=OcrReader.Candidates("消耗1.2万\n成交金额2.4亿元\n成单人数1.3万人");return x.GetValueOrDefault("消耗")==12000&&x.GetValueOrDefault("GMV")==240000000&&x.GetValueOrDefault("人数")==13000;});
        Check("Latest facts survive long sessions",()=>{var s=new Session{Day=DateTime.Today.AddDays(-1),Notes="LATEST_NOTE_21"};for(int i=0;i<240;i++)s.Snapshots.Add(new(){At=s.Day.AddMinutes(i),Spend=i,Gmv=i*2,Note=i==239?"NEWEST_SNAPSHOT_21":new string('测',60)});s.Changes.Add(new(){Text="LATEST_CHANGE_21"});var r=new Room{Finance=s,Messages=[new(){Text="test"}]};var q=JsonSerializer.Serialize(AiClient.BuildRequest(r,"test",[]));return q.Contains("NEWEST_SNAPSHOT_21")&&q.Contains("LATEST_NOTE_21")&&q.Contains("LATEST_CHANGE_21");});
        Check("Pinned business constraints survive history trimming",()=>{var r=JsonSerializer.Deserialize<Room>("{\"Business\":{\"Constraints\":\"NEVER_RAISE_MY_CEILING_21\"}}")!;for(int i=0;i<20;i++)r.Messages.Add(new(){Role=i%2==0?"user":"assistant",Text="turn"+i});return JsonSerializer.Serialize(AiClient.BuildRequest(r,"test",[])).Contains("NEVER_RAISE_MY_CEILING_21");});
        bool Reject(Action action){try{action();return false;}catch(InvalidDataException){return true;}}
        Room Case()=>new(){Finance=new(){Day=DateTime.Today.AddDays(-1),Price=1200,Goal="成交金额",Target=6.0m,Budget=200},Business=new(){PlanId="10001",MaxCost=200},Facts=new(){ScopeConfirmed=true,DuringLive="已开启",Approval="通过",Balance="充足",Account="正常",Materials="可投",Targeting="已核对",Conflict="无",LiveStart=DateTime.Today.AddDays(-1).AddHours(20),LiveEnd=DateTime.Today.AddDays(-1).AddHours(21),EnabledStart=DateTime.Today.AddDays(-1).AddHours(20),EnabledEnd=DateTime.Today.AddDays(-1).AddHours(21)}};
        MaterialBatch Batch(Room r,decimal spend=.31m,string title="示例视频")=>new(){Kind="视频",PlanId=r.Business.PlanId,Start=r.Finance.Day,End=r.Finance.Day.AddDays(1),ScopeConfirmed=true,Rows=[new(){Id="12345",Title=title,Source="智能优选视频",Spend=spend}]};
        Check("1200 over 200 is a reference ROI of 6.0",()=>Decision.Economy(Case()).ReferenceRoi==6.0m);
        Check("Retained-cost goal needs an explicit retention assumption",()=>{var r=Case();r.Business.CostBasis="未退款订单";return Decision.Economy(r).ReferenceRoi==null;});
        Check("80 percent retention converts 200 retained cost to 160 paid cost",()=>{var r=Case();r.Business.CostBasis="未退款订单";r.Finance.Retention=80;var v=Decision.Economy(r);return v.PaymentCostCeiling==160&&v.ReferenceRoi==7.5m;});
        Check("Mixed selling does not infer a whole-room ROI from one price",()=>{var r=Case();r.Business.SellingMode="多商品";return Decision.Economy(r).MixRoi==null&&Decision.Cards(r).Any(c=>c.Id=="mix");});
        Check("Mixed target weights revenue and allowed costs, not ROI averages",()=>{var r=Case();r.Business.SellingMode="多商品";r.Business.Products=[new(){Name="高价",Price=1200,AllowedCost=200,ExpectedOrders=1},new(){Name="低价",Price=25m,AllowedCost=5,ExpectedOrders=2}];return Decision.Economy(r).MixRoi==(1200+50m)/210;});
        Check("Relaxing ROI warns about a hard business ceiling",()=>{var r=Case();r.Finance.Target=5;return Decision.Cards(r).Any(c=>c.Id=="ceiling");});
        Check("Historical enabled state is not replaced by current pause",()=>{var r=Case();return Decision.OverlapMinutes(r.Facts)==60&&!Decision.Cards(r).Any(c=>c.Id=="eligibility");});
        Check("A missing balance check remains unknown",()=>{var r=Case();r.Facts.Balance="未知";var cards=Decision.Cards(r);return cards.Any(c=>c.Id=="unknown")&&!cards.Any(c=>c.Id=="eligibility");});
        Check("Non-overlapping windows block delivery before bidding advice",()=>{var r=Case();r.Facts.EnabledStart=r.Facts.LiveEnd;r.Facts.EnabledEnd=r.Facts.LiveEnd!.Value.AddHours(1);return Decision.OverlapMinutes(r.Facts)==0&&Decision.Cards(r).Any(c=>c.Id=="eligibility");});
        Check("Near-zero spend is a candidate diagnosis, not a confirmed ROI cause",()=>{var r=Case();r.Finance.Snapshots.Add(new(){At=r.Finance.Day.AddHours(21),Spend=.31m});return Decision.Cards(r).Any(c=>c.Id=="low-delivery"&&c.Level=="待验证");});
        Check("A title alone does not assign irrelevant status",()=>{var r=Case();Decision.AddReport(r,Batch(r,title:"宝宝互动"));return !Decision.Cards(r).Any(c=>c.Id=="irrelevant");});
        Check("Human confirmed irrelevant material is actionable until resolved",()=>{var r=Case();Decision.AddReport(r,Batch(r));var v=new MaterialReview{Id="12345",Relevance="不相关"};r.MaterialReviews.Add(v);bool before=Decision.Cards(r).Any(c=>c.Id=="irrelevant");v.Resolution="已排除";return before&&!Decision.Cards(r).Any(c=>c.Id=="irrelevant");});
        Check("A repeated material export does not double count",()=>{var r=Case();Decision.AddReport(r,Batch(r));Decision.AddReport(r,Batch(r));return Decision.CurrentReports(r).Sum(b=>b.Rows.Sum(x=>x.Spend))==.31m;});
        Check("A report with a different date or plan is excluded",()=>{var r=Case();var b=Batch(r);b.PlanId="20002";Decision.AddReport(r,b);return Decision.CurrentReports(r).Count==0;});
        Check("Blank image title and Invalid Date remain unknown",()=>{var rows=new List<Dictionary<string,string>>{new(){["图文标题"]="",["素材ID"]="123",["素材添加来源"]="自选投放图文",["创建时间"]="Invalid Date",["消耗(元)"]="0",["全域成交金额(元)"]="0",["全域成交订单数"]="0"}};var b=MaterialImport.ReadRows(rows,"test.xlsx");return b.Rows[0].Title==""&&b.Rows[0].Created==null;});
        Check("Missing material spend is rejected rather than treated as zero",()=>Reject(()=>MaterialImport.ReadRows([new(){["视频标题"]="a",["素材ID"]="1",["素材添加来源"]="自选",["创建时间"]="",["消耗(元)"]="",["全域成交金额(元)"]="0",["全域成交订单数"]="0"}],"test.xlsx")));
        Check("Duplicate material IDs do not mutate the current report list",()=>{var r=Case();var b=Batch(r);b.Rows.Add(b.Rows[0]);return Reject(()=>Decision.AddReport(r,b))&&r.MaterialBatches.Count==0;});
        Check("Unknown OCR units and negative amounts do not become positive candidates",()=>{var x=OcrReader.Candidates("消耗1.2w\n成交金额-20元");return x.Count==0;});
        Check("Future new snapshots are rejected",()=>Reject(()=>Rules.ValidateSnapshot(new(){At=DateTime.Now.AddHours(2)})));
        Check("Loaded future snapshots are excluded from usable metrics",()=>{var r=Case();r.Finance.Snapshots=[new(){At=r.Finance.Day,Spend=10},new(){At=DateTime.Now.AddDays(1),Spend=9999}];return r.Finance.UsableSnapshots.Last().Spend==10&&Decision.Cards(r).Any(c=>c.Id=="future");});
        Room ActionCase(){var r=Case();var day=r.Finance.Day.AddHours(20);r.Finance.Snapshots=[new(){At=day,Spend=0,Gmv=0,Buyers=0},new(){At=day.AddMinutes(10),Spend=50,Gmv=100,Buyers=1},new(){At=day.AddMinutes(40),Spend=100,Gmv=300,Buyers=2}];return r;}
        FollowUp ActionFor(Room r)=>new(){Title="清理无关素材",ExecutedAt=r.Finance.Day.AddHours(20).AddMinutes(10),ReviewMinutes=30,Metric="支付ROI"};
        Check("Action review compares interval ROI, not cumulative ROI",()=>{var r=ActionCase();var a=ActionFor(r);var v=Decision.Evaluate(r,a);return v.BeforeValue==2&&v.AfterValue==4&&v.Status=="可复查";});
        Check("An unexecuted action cannot claim effects",()=>{var r=ActionCase();var a=ActionFor(r);a.ExecutedAt=null;return Decision.Evaluate(r,a).Status=="待执行";});
        Check("A review waits for its configured observation window",()=>{var r=ActionCase();var a=ActionFor(r);a.ReviewMinutes=60;return Decision.Evaluate(r,a).Status=="等待观察窗";});
        Check("Cumulative backfill blocks action effect calculations",()=>{var r=ActionCase();r.Finance.Snapshots[^1].Spend=20;return Decision.Evaluate(r,ActionFor(r)).Status=="口径待核对";});
        Check("A zero denominator remains unknown in action review",()=>{var r=ActionCase();r.Finance.Snapshots[^1].Spend=50;return Decision.Evaluate(r,ActionFor(r)).Status=="分母不足";});
        Check("Future executions are rejected",()=>Reject(()=>Decision.ValidateAction(new(){Title="x",ExecutedAt=DateTime.Now.AddDays(1)})));
        Check("Version two workspaces migrate without inventing business values",()=>{var p=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".json");try{var r=Case();File.WriteAllText(p,JsonSerializer.Serialize(new{Version=2,Selected=r.Finance.Id,Rooms=new[]{new{Finance=r.Finance,Messages=Array.Empty<ChatItem>(),Calls=Array.Empty<CallLog>(),Events=Array.Empty<string>()}}}));var w=Workspace.Load(p);return w.Version==3&&w.Current.Business.MaxCost==null&&w.Current.Finance.Target==6.0m;}finally{if(File.Exists(p))File.Delete(p);}});
        Check("User records are data input, not developer instructions",()=>{var r=Case();r.Business.Constraints="UNTRUSTED_USER_RECORD_21";r.Messages.Add(new(){Text="test"});var q=JsonSerializer.SerializeToElement(AiClient.BuildRequest(r,"test",[]));return !q.GetProperty("instructions").GetString()!.Contains("UNTRUSTED_USER_RECORD_21")&&q.GetProperty("input")[0].GetProperty("content")[0].GetProperty("text").GetString()!.Contains("UNTRUSTED_USER_RECORD_21");});
        Check("Export omits structured buyer and order identifiers",()=>{var r=Case();r.Finance.Orders.Add(new(){Id="PRIVATE_ORDER_21",Buyer="PRIVATE_BUYER_21",Product="示例",Channel="直播",Paid=1200,PaidTime=r.Finance.Day,OrderTime=r.Finance.Day});var text=r.ExportText();return !text.Contains("PRIVATE_ORDER_21")&&!text.Contains("PRIVATE_BUYER_21");});
        Check("Rejected business commands preserve the previous financial values",()=>{var r=Case();return Reject(()=>DecisionCommands.Apply(r,"business",JsonSerializer.SerializeToElement(new{business=new BusinessGoal{MaxCost=-1},refPrice=999})))&&r.Business.MaxCost==200&&r.Finance.Price==1200;});
        Check("Business save uses backend math and preserves persistent constraints",()=>{var r=Case();DecisionCommands.Apply(r,"business",JsonSerializer.SerializeToElement(new{business=new BusinessGoal{PlanId="10001",MaxCost=200,Constraints="不可超支"},refPrice=1600,refRetention=80}));return Decision.Economy(r).ReferenceRoi==8&&r.Business.Constraints=="不可超支";});
        Check("Material confirmation requires an existing asset",()=>{var r=Case();return Reject(()=>DecisionCommands.Apply(r,"materialReview",JsonSerializer.SerializeToElement(new MaterialReview{Id="999",Relevance="不相关"})))&&r.MaterialReviews.Count==0;});
        Check("An unexecuted action cannot be marked reviewed",()=>{var r=Case();return Reject(()=>DecisionCommands.Apply(r,"followUp",JsonSerializer.SerializeToElement(new{item=new FollowUp{Title="x",Assessment="已完成"},markReviewed=true})))&&r.FollowUps.Count==0;});
        Check("An observed action can be explicitly reviewed by its owner",()=>{var r=ActionCase();var a=ActionFor(r);a.Assessment="区间ROI提高，但样本小不能确定因果";DecisionCommands.Apply(r,"followUp",JsonSerializer.SerializeToElement(new{item=a,markReviewed=true}));return r.FollowUps.Single().ReviewedAt.HasValue;});
        Check("Reviewed evidence and conclusions are immutable",()=>{var r=ActionCase();var a=ActionFor(r);a.Assessment="小样本，暂不外推";DecisionCommands.Apply(r,"followUp",JsonSerializer.SerializeToElement(new{item=a,markReviewed=true}));var changed=JsonSerializer.Deserialize<FollowUp>(JsonSerializer.Serialize(r.FollowUps.Single()))!;changed.Assessment="篡改结论";return Reject(()=>DecisionCommands.Apply(r,"followUp",JsonSerializer.SerializeToElement(new{item=changed,markReviewed=false})))&&r.FollowUps.Single().Assessment=="小样本，暂不外推";});
        Check("Unchanged OCR metrics ignore changed screenshot pixel hashes",()=>DecisionCommands.ObservationKey("a",new Dictionary<string,decimal>{{"消耗",10},{"GMV",20}})==DecisionCommands.ObservationKey("b",new Dictionary<string,decimal>{{"GMV",20},{"消耗",10}}));
        Check("Insufficient OCR falls back to screenshot changes",()=>DecisionCommands.ObservationKey("a",new Dictionary<string,decimal>{{"消耗",10}})=="a");
        Check("Version three archives retain business, materials and follow-ups",()=>{var r=ActionCase();r.Business.Constraints="固定约束";Decision.AddReport(r,Batch(r));r.MaterialReviews.Add(new(){Id="12345",Relevance="不相关",Resolution="已排除"});r.FollowUps.Add(ActionFor(r));var w=new Workspace{Rooms=[r],Selected=r.Finance.Id};var p=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".zip");try{WorkspaceArchive.Save(w,p);var next=WorkspaceArchive.Read(p).Data.Current;return next.Business.Constraints=="固定约束"&&next.MaterialBatches.Single().Rows.Single().Spend==.31m&&next.MaterialReviews.Single().Resolution=="已排除"&&Decision.Evaluate(next,next.FollowUps.Single()).AfterValue==4;}finally{if(File.Exists(p))File.Delete(p);}});
        Check("New snapshots must match this room's date range",()=>{var r=Case();return Reject(()=>Rules.ValidateSnapshot(new(){At=r.Finance.Day.AddDays(-1)},scope:r.Finance));});
        Check("Loaded out-of-scope snapshots do not enter current metrics",()=>{var r=Case();r.Finance.Snapshots=[new(){At=r.Finance.Day.AddHours(20),Spend=10},new(){At=r.Finance.Day.AddDays(1).AddHours(1),Spend=999}];return r.Finance.UsableSnapshots.Single().Spend==10&&Decision.Cards(r).Any(c=>c.Id=="snapshot-scope");});
        Check("Explicit cross-midnight range includes its closing snapshot",()=>{var r=Case();r.Finance.Start=r.Finance.Day.AddHours(20);r.Finance.End=r.Finance.Day.AddDays(1).AddHours(1);r.Finance.Snapshots=[new(){At=r.Finance.End.Value,Spend=10}];Rules.ValidateSnapshot(r.Finance.Snapshots[0],scope:r.Finance);return r.Finance.UsableSnapshots.Single().Spend==10;});
        Check("All shipped UI resources and the chosen C icon are embedded",()=>{var assembly=typeof(UpgradeChecks).Assembly;var assets=assembly.GetManifestResourceNames();using var stream=assembly.GetManifestResourceStream("LiveAdStudio.Assets.app.ico")!;using var icon=new Icon(stream,32,32);using var logo=Image.FromStream(assembly.GetManifestResourceStream("LiveAdStudio.Ui.app-logo.png")!);return icon.Width==32&&logo.Width==256&&new[]{"index.html","decision.js","decision.css","app-logo.png"}.All(n=>assets.Contains("LiveAdStudio.Ui."+n));});
        // ponytail: a generated read-only state exercises the shipped UI without loading user data or credentials.
        var demo=Case();demo.Finance.Name="演示门店 · 直播复盘";demo.Finance.Snapshots=[new(){At=demo.Finance.Day.AddHours(21),Spend=.31m,Gmv=0,Buyers=0}];demo.Facts.Approval="未知";demo.Business.SellingMode="多商品";Decision.AddReport(demo,Batch(demo,title:"风景 · 演示素材"));demo.MaterialReviews.Add(new(){Id="12345",Relevance="不相关"});demo.FollowUps.Add(new(){Title="核对可投素材与审核状态",Reason="消耗很少，尚不能确定是ROI限制",Expected="核实投放前置条件",StopCondition="未确认前不追加预算"});
        var dw=new Workspace{Rooms=[demo],Selected=demo.Finance.Id};File.WriteAllText(output+".ui.json",JsonSerializer.Serialize(StateView.Build(dw),new JsonSerializerOptions{PropertyNamingPolicy=JsonNamingPolicy.CamelCase}));
        File.WriteAllLines(output,results);if(results.Any(x=>x.StartsWith("FAIL")))throw new InvalidDataException(string.Join("; ",results.Where(x=>x.StartsWith("FAIL"))));
    }
}
